import json
with open('/workspace/candidate_trace.json') as f:
    data = json.load(f)
# Validate all required fields
required = ['step', 'file', 'function', 'line', 'var', 'code', 'note']
for i, step in enumerate(data):
    missing = [k for k in required if k not in step]
    extra = [k for k in step if k not in required and k != 'line_end']
    if missing:
        print(f'ERROR Step {i+1}: missing {missing}')
    if extra:
        print(f'WARN Step {i+1}: extra fields {extra}')
    if not isinstance(step['step'], int) or step['step'] != i + 1:
        print(f'ERROR Step {i+1}: step number mismatch')
    if not isinstance(step['file'], str) or not step['file']:
        print(f'ERROR Step {i+1}: file empty')
    if not isinstance(step['function'], str) or not step['function']:
        print(f'ERROR Step {i+1}: function empty')
    if step['line'] is not None and not isinstance(step['line'], int):
        print(f'ERROR Step {i+1}: line not int or null')
    if not isinstance(step['var'], str) or not step['var']:
        print(f'ERROR Step {i+1}: var empty')
    if not isinstance(step['code'], str) or not step['code']:
        print(f'ERROR Step {i+1}: code empty')
    if not isinstance(step['note'], str) or not step['note']:
        print(f'ERROR Step {i+1}: note empty')
print('Validation complete')
print(f'Total steps: {len(data)}')
print(f'Is array: {isinstance(data, list)}')
"

